arguments.argument:
sx = floor(view_xview / fgrid)
sy = floor(view_yview / fgrid)
ex = sx + dw
ey = sy + dh

surface_set_target(surf)
draw_clear(0)

texture_set_interpolation(true)

for (j = sy; j < ey; j += 1)
{
    for (i = sx; i < ex; i += 1)
    {
        switch(ds_grid_get(fog_id, i, j))
        {
            case 1: draw_sprite_ext(spr_fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 1); break;
            case 2: draw_sprite_ext(spr_fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, c_dkgray, 1); break;
            case 0: draw_sprite_ext(spr_fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 0); break;
        }
    }
}

texture_set_interpolation(false)

surface_reset_target()
